using System;
using System.Collections.Generic;
using System.Linq;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;
using Jellyfin.Server.Migrations.Routines;
using Jellyfin.Database.Implementations;
using Jellyfin.Database.Implementations.Entities;
using MediaBrowser.Controller.Library;
using Microsoft.EntityFrameworkCore;

namespace Jellyfin.Server.Migrations.Routines
{
    internal class MigrateLinkedChildrenTests
    {
        [Fact]
        public void Perform_LogsNoItemsFromDeletedLibrariesFound_WhenNoOrphanedIds()
        {
            // Arrange
            var loggerMock = new Mock<ILogger<MigrateLinkedChildren>>();
            var dbContextMock = new Mock<JellyfinDbContext>(MockBehavior.Strict, new DbContextOptions<JellyfinDbContext>(), null, null, null);
            var dbContextFactoryMock = new Mock<IDbContextFactory<JellyfinDbContext>>();
            var libraryManagerMock = new Mock<ILibraryManager>();
            var appHostMock = new Mock<IServerApplicationHost>();
            var appPathsMock = new Mock<IServerApplicationPaths>();

            // Setup DbContextFactory to return our mocked DbContext
            dbContextFactoryMock.Setup(f => f.CreateDbContext()).Returns(dbContextMock.Object);

            // Setup BaseItems DbSet to simulate no orphaned items from deleted libraries
            var baseItemsData = new List<BaseItemEntity>
            {
                new BaseItemEntity { Id = Guid.NewGuid(), TopParentId = null, Type = "MediaBrowser.Controller.Entities.Movies.Movie" },
                new BaseItemEntity { Id = Guid.NewGuid(), TopParentId = Guid.NewGuid(), Type = "MediaBrowser.Controller.Entities.Movies.Movie" }
            }.AsQueryable();

            var baseItemsDbSetMock = new Mock<DbSet<BaseItemEntity>>();
            baseItemsDbSetMock.As<IQueryable<BaseItemEntity>>().Setup(m => m.Provider).Returns(baseItemsData.Provider);
            baseItemsDbSetMock.As<IQueryable<BaseItemEntity>>().Setup(m => m.Expression).Returns(baseItemsData.Expression);
            baseItemsDbSetMock.As<IQueryable<BaseItemEntity>>().Setup(m => m.ElementType).Returns(baseItemsData.ElementType);
            baseItemsDbSetMock.As<IQueryable<BaseItemEntity>>().Setup(m => m.GetEnumerator()).Returns(baseItemsData.GetEnumerator());

            dbContextMock.Setup(c => c.BaseItems).Returns(baseItemsDbSetMock.Object);

            // Setup LinkedChildren DbSet to empty
            var linkedChildrenData = new List<LinkedChildEntity>().AsQueryable();
            var linkedChildrenDbSetMock = new Mock<DbSet<LinkedChildEntity>>();
            linkedChildrenDbSetMock.As<IQueryable<LinkedChildEntity>>().Setup(m => m.Provider).Returns(linkedChildrenData.Provider);
            linkedChildrenDbSetMock.As<IQueryable<LinkedChildEntity>>().Setup(m => m.Expression).Returns(linkedChildrenData.Expression);
            linkedChildrenDbSetMock.As<IQueryable<LinkedChildEntity>>().Setup(m => m.ElementType).Returns(linkedChildrenData.ElementType);
            linkedChildrenDbSetMock.As<IQueryable<LinkedChildEntity>>().Setup(m => m.GetEnumerator()).Returns(linkedChildrenData.GetEnumerator());

            dbContextMock.Setup(c => c.LinkedChildren).Returns(linkedChildrenDbSetMock.Object);

            // Create instance of MigrateLinkedChildren with mocked dependencies
            var loggerFactoryMock = new Mock<ILoggerFactory>();
            loggerFactoryMock.Setup(f => f.CreateLogger<MigrateLinkedChildren>()).Returns(loggerMock.Object);

            var migrate = (MigrateLinkedChildren)Activator.CreateInstance(
                typeof(MigrateLinkedChildren),
                loggerFactoryMock.Object,
                dbContextFactoryMock.Object,
                libraryManagerMock.Object,
                appHostMock.Object,
                appPathsMock.Object);

            // Act
            migrate.Perform();

            // Assert
            loggerMock.Verify(
                x => x.Log(
                    LogLevel.Information,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("No items from deleted libraries found.")),
                    null,
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.AtLeastOnce);
        }
    }
}
